def absolute_value(number, **_extra):
    import json, os, datetime, math, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0435000" if __import__("os").path.isdir("./environment_mix/0435000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Ensure audit/usage collection exists (not part of schema, but required for observable dynamics)
    usage_file = "usage.json"
    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    # Quota/rate policy (no schema provided): implement conservative defaults
    # - rate: 120 requests/minute (sliding window)
    # - daily quota: 5000 requests/day
    now = datetime.datetime.utcnow()
    window_s = 60
    rate_limit = 120
    daily_quota = 5000

    def _ts(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    # Purge very old usage to keep file bounded (retain 8 days)
    cutoff = now - datetime.timedelta(days=8)
    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            if isinstance(s, str):
                return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        return None

    kept = []
    for r in usage:
        dt = _parse_ts(r.get("timestamp"))
        if dt is None or dt >= cutoff:
            kept.append(r)
    usage = kept

    # Enforce limits
    wstart = now - datetime.timedelta(seconds=window_s)
    dstart = now - datetime.timedelta(days=1)

    def _count_since(dt0):
        c = 0
        for r in usage:
            dt = _parse_ts(r.get("timestamp"))
            if dt is not None and dt >= dt0:
                c += 1
        return c

    if _count_since(wstart) >= rate_limit:
        # record refused call
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "absolute_value", "status": "RATE_LIMIT", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate_limit, window_seconds=window_s)

    if _count_since(dstart) >= daily_quota:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "absolute_value", "status": "QUOTA_EXCEEDED", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=daily_quota, period="day")

    # Validate input
    if number is None:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "absolute_value", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Missing required field: number", field="number")

    if not isinstance(number, (int, float)) or isinstance(number, bool):
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "absolute_value", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Field 'number' must be a valid number", field="number")

    if not math.isfinite(float(number)):
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "absolute_value", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Field 'number' must be finite", field="number")

    # Real datastore interaction: read and advance random_seed deterministically (observable state change)
    state = _load("state.json")
    if not isinstance(state, list):
        state = []
    if len(state) == 0:
        state.append({"random_seed": 0})

    # Mutation as traffic counter: increment random_seed by 1 per call
    if not isinstance(state[0], dict):
        state = [{"random_seed": 0}]
