    if not isinstance(rs, int):
        rs = 0
    state[0]["random_seed"] = rs + 1
    _save("state.json", state)

    result = abs(float(number))

    latency_ms = int((time.time() - t0) * 1000)
    usage.append({"endpoint": "absolute_value", "status": "OK", "timestamp": _ts(now), "latency_ms": latency_ms})
    _save(usage_file, usage)
    return {"result": result, "state": {"random_seed": state[0]["random_seed"]}}

