    length_to_m = {"in": 0.0254, "ft": 0.3048, "yd": 0.9144, "mi": 1609.344, "m": 1.0, "cm": 0.01, "km": 1000.0}
    mass_to_kg = {"lb": 0.45359237, "kg": 1.0}
    temp_units = {"c", "celsius", "f", "fahrenheit"}

    def _convert_length(v, uin, uout):
        vin_m = v * length_to_m[uin]
        return vin_m / length_to_m[uout]

    def _convert_mass(v, uin, uout):
        vin_kg = v * mass_to_kg[uin]
        return vin_kg / mass_to_kg[uout]

    def _convert_temp(v, uin, uout):
        # normalize to celsius then out
        if uin in ("c", "celsius"):
            c = v
        elif uin in ("f", "fahrenheit"):
            c = (v - 32.0) * (5.0 / 9.0)
        else:
            raise KeyError
        if uout in ("c", "celsius"):
            return c
        elif uout in ("f", "fahrenheit"):
            return c * (9.0 / 5.0) + 32.0
        else:
            raise KeyError

