        if unit_in == unit_out:
            result = float(value)
        elif unit_in in length_to_m and unit_out in length_to_m:
            result = _convert_length(float(value), unit_in, unit_out)
        elif unit_in in mass_to_kg and unit_out in mass_to_kg:
            result = _convert_mass(float(value), unit_in, unit_out)
        elif unit_in in temp_units and unit_out in temp_units:
