        return _err("VALIDATION_ERROR", "Unsupported or incompatible unit pair", unit_in=unit_in, unit_out=unit_out)

    # Datastore interaction: increment random_seed by 1 per successful call
    state = _load("state.json")
    if not isinstance(state, list):
        state = []
    if len(state) == 0:
        state.append({"random_seed": 0})
    if not isinstance(state[0], dict):
        state = [{"random_seed": 0}]
    rs = state[0].get("random_seed", 0)
    if not isinstance(rs, int):
        rs = 0
    state[0]["random_seed"] = rs + 1
    _save("state.json", state)

    latency_ms = int((time.time() - t0) * 1000)
    usage.append({"endpoint": "imperial_si_conversion", "status": "OK", "timestamp": _ts(now), "latency_ms": latency_ms})
    _save(usage_file, usage)
    return {"result": result, "unit_out": unit_out, "state": {"random_seed": state[0]["random_seed"]}}

