def si_unit_conversion(value, unit_in, unit_out, **_extra):
    import json, os, datetime, math, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0435000" if __import__("os").path.isdir("./environment_mix/0435000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    usage_file = "usage.json"
    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    now = datetime.datetime.utcnow()
    window_s = 60
    rate_limit = 120
    daily_quota = 5000

    def _ts(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    cutoff = now - datetime.timedelta(days=8)
    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            if isinstance(s, str):
                return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        return None

    usage = [r for r in usage if (_parse_ts(r.get("timestamp")) or now) >= cutoff]

    wstart = now - datetime.timedelta(seconds=window_s)
    dstart = now - datetime.timedelta(days=1)
    def _count_since(dt0):
        c = 0
        for r in usage:
            dt = _parse_ts(r.get("timestamp"))
            if dt is not None and dt >= dt0:
                c += 1
        return c

    if _count_since(wstart) >= rate_limit:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "RATE_LIMIT", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate_limit, window_seconds=window_s)

    if _count_since(dstart) >= daily_quota:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "QUOTA_EXCEEDED", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=daily_quota, period="day")

    # Validate required
    for fname, v in (("value", value), ("unit_in", unit_in), ("unit_out", unit_out)):
        if v is None:
            latency_ms = int((time.time() - t0) * 1000)
            usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
            _save(usage_file, usage)
            return _err("VALIDATION_ERROR", f"Missing required field: {fname}", field=fname)

    if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(float(value)):
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Field 'value' must be a valid finite number", field="value")

    if not isinstance(unit_in, str) or not unit_in.strip():
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Field 'unit_in' must be a non-empty string", field="unit_in")
    if not isinstance(unit_out, str) or not unit_out.strip():
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Field 'unit_out' must be a non-empty string", field="unit_out")

    unit_in = unit_in.strip().lower()
    unit_out = unit_out.strip().lower()

    # SI conversions with dimensions (length, mass, time)
    length_to_m = {"m": 1.0, "km": 1000.0, "cm": 0.01, "mm": 0.001, "um": 1e-6, "nm": 1e-9}
    mass_to_kg = {"kg": 1.0, "g": 0.001, "mg": 1e-6}
    time_to_s = {"s": 1.0, "ms": 1e-3, "us": 1e-6, "ns": 1e-9, "min": 60.0, "h": 3600.0}

    def _dim(u):
        if u in length_to_m: return "length"
        if u in mass_to_kg: return "mass"
        if u in time_to_s: return "time"
        return None

    din = _dim(unit_in)
    dout = _dim(unit_out)
    if din is None or dout is None:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Unknown/unsupported unit string", unit_in=unit_in, unit_out=unit_out)

    if din != dout:
        latency_ms = int((time.time() - t0) * 1000)
        usage.append({"endpoint": "si_unit_conversion", "status": "VALIDATION_ERROR", "timestamp": _ts(now), "latency_ms": latency_ms})
        _save(usage_file, usage)
        return _err("VALIDATION_ERROR", "Incompatible unit dimensions", unit_in=unit_in, unit_out=unit_out, dimension_in=din, dimension_out=dout)

    v = float(value)
    if unit_in == unit_out:
        result = v
    else:
        if din == "length":
            result = v * length_to_m[unit_in] / length_to_m[unit_out]
        elif din == "mass":
            result = v * mass_to_kg[unit_in] / mass_to_kg[unit_out]
        else:  # time
            result = v * time_to_s[unit_in] / time_to_s[unit_out]

    # Datastore interaction: increment random_seed by 1 per successful call
    state = _load("state.json")
    if not isinstance(state, list):
        state = []
    if len(state) == 0:
        state.append({"random_seed": 0})
    if not isinstance(state[0], dict):
        state = [{"random_seed": 0}]
    rs = state[0].get("random_seed", 0)
    if not isinstance(rs, int):
        rs = 0
    state[0]["random_seed"] = rs + 1
    _save("state.json", state)

    latency_ms = int((time.time() - t0) * 1000)
    usage.append({"endpoint": "si_unit_conversion", "status": "OK", "timestamp": _ts(now), "latency_ms": latency_ms})
    _save(usage_file, usage)
    return {"result": result, "unit_out": unit_out, "state": {"random_seed": state[0]["random_seed"]}}

